349	        final Map<String, PrivacyEnforcementAction> bidderNameToAction = new HashMap<>();
350	
351	        final Map<Integer, Set<String>> vendorIdToBidders = bidderToVendorId.entrySet().stream()
352	                .filter(entry -> entry.getValue() != null)
353	                .collect(Collectors.groupingBy(
354	                        Map.Entry::getValue,
355	                        Collectors.mapping(Map.Entry::getKey, Collectors.toSet())));
356	
357	        for (final VendorPermission vendorPermission : vendorPermissions) {
358	            final Integer vendorId = vendorPermission.getVendorId();
