360	            if (vendorIdToBidders.containsKey(vendorId)) {
361	                final PrivacyEnforcementAction action = vendorPermission.getPrivacyEnforcementAction();
362	                vendorIdToBidders.get(vendorId).forEach(bidderName -> bidderNameToAction.put(bidderName, action));
363	            }
