367	        bidderToVendorId.entrySet().stream()
368	                .filter(entry -> entry.getValue() == null)
369	                .map(Map.Entry::getKey)
370	                .forEach(bidder -> bidderNameToAction.put(bidder, restrictAllButAnalyticsAndAuction()));
